function addDays(iso, n){ var d=new Date(iso+'T00:00:00Z'); d.setUTCDate(d.getUTCDate()+n); return d.toISOString().slice(0,10); }
function predict(startISO, cycleLen, periodLen, count){
  cycleLen=cycleLen>0?cycleLen:28; periodLen=periodLen>0?periodLen:5; count=count>0?count:3;
  var out=[];
  for(var i=0;i<count;i++){
    var s=addDays(startISO, i*cycleLen);
    var e=addDays(s, periodLen-1);
    var ovDay=Math.max(1, cycleLen-14); // 排卵期（距月经首日天数）
    var fs=addDays(s, ovDay-6); // 易孕窗起点：排卵前 5 天
    var fe=addDays(s, ovDay-1); // 排卵日
    out.push({start:s,end:e,fertileStart:fs,fertileEnd:fe});
  }
  return out;
}
var EXPORTS={predict:predict,addDays:addDays};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PeriodForgePure = EXPORTS; }
